  background: #0f172a;
}
.navbar a {
  color: #f8fafc;
  text-decoration: none;
}
.logo {
  font-weight: bold;
  font-size: 20px;
}

/* Tầng 2: con trực tiếp là các li — flex của .navbar KHÔNG chạm tới chúng */
.menu {
  display: flex;
  gap: 24px;
  list-style: none;   /* bỏ chấm đầu dòng */
  margin: 0;          /* bỏ lề mặc định của ul */
